#pragma once

// The provider-neutral turn loop behind IAgentService. It owns the
// transcript of the turn: the chat's record, then what the turn adds, which
// it hands back to the record once a later request can follow on from it.
// It runs the model's tool calls one at a time in the order written, answers
// the rest unrun after a failure, refuses calls to tools not offered or with
// arguments off the contract, and sends fired skills after what fired them.
// Everything on the wire goes through the IProviderCodec it is built with,
// and nothing here reads provider JSON.
//
// Network callbacks only append protected input; all parsing and AgentEvent
// delivery happens from poll() on the GUI thread.

#include "AgentService.hpp"
#include "AgentTransport.hpp"
#include "ProviderCodec.hpp"
#include "ProviderProfile.hpp"

#include <deque>
#include <functional>
#include <memory>
#include <mutex>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

// A request about to be sent. The headers stay out: they hold the credential.
struct SentRequest
{
    std::string           provider;
    std::string           chat_key; // empty for a request of no chat
    std::string           turn_id;
    unsigned              sequence{0}; // which request of the turn, from 1
    const nlohmann::json& body;
};

// The name JusPrin's gateway keeps a chat's turns and credits under, sent as
// X-JusPrin-Chat: the chat key hashed, so the gateway never sees a project or
// chat id.
std::string gateway_chat_id(const std::string& chat_key);

struct ProviderAgentConfig
{
    // The provider, with the configured model and endpoint in place of the
    // row's defaults where the person set them.
    ProviderProfile profile;
    std::string     api_key;
    std::function<void(const AgentUsage&)> usage_listener;
