anchor='TEST_CASE("what the codec reports ends the turn as it says", "[agent][loop][errors]")'
new='''TEST_CASE("an answer no expected-errors entry names stops the turn with the service's status and text", "[agent][loop][errors]")
{
    using Catch::Matchers::ContainsSubstring;
    const std::string not_found = R"({"error":{"message":"The model `gpt-x` does not exist","type":"invalid_request_error","code":"model_not_found"}})";
    for (const unsigned status : {400u, 402u, 403u, 404u, 409u, 422u}) {
        CAPTURE(status);
        Harness h;
        REQUIRE(h.agent->start(request_fixture()));
        h.fake->refuse(status, not_found);
        CHECK_THROWS_WITH(h.poll_until(AgentEventKind::Failed),
                          ContainsSubstring("Test Provider answered HTTP " + std::to_string(status)) &&
                              ContainsSubstring("model_not_found") && ContainsSubstring("assistant-7-attempt-1"));
        // The turn stopped there: nothing is waiting, nothing more arrives.
        CHECK_FALSE(h.agent->busy());
        CHECK(h.fake->cancelled);
        CHECK_FALSE(h.agent->poll());
    }
    // A 429 that is not about speed: OpenAI's for a key whose account has no
    // money left, which no entry names.
    Harness h;
    REQUIRE(h.agent->start(request_fixture()));
    h.fake->refuse(429, R"({"error":{"message":"You exceeded your current quota","type":"insufficient_quota","code":"insufficient_quota"}})");
    CHECK_THROWS_WITH(h.poll_until(AgentEventKind::Failed), ContainsSubstring("HTTP 429") && ContainsSubstring("insufficient_quota"));
}

