        REQUIRE(event->error.has_value());
        return *event->error;
    };
    CHECK(answer(504, gateway("timeout")).code == "timeout");
    CHECK(answer(503, gateway("unavailable")).code == "service_unavailable");
    CHECK(answer(503, gateway("busy")).code == "rate_limited");
    CHECK(answer(429, gateway("rate_limited")).code == "rate_limited");
    CHECK(answer(413, gateway("request_too_large")).code == "request_too_large");
    // The gateway's own unexpected failure, which it has already reported.
    const AgentError ours = answer(500, gateway("server_error"));
    CHECK(ours.code == "server_error");
    CHECK(ours.message == "Something went wrong on our side");
    CHECK_FALSE(ours.retryable);
    // The app's own request refused, a 402 without the numbers the gateway
    // always sends, and a page that is not the gateway's: no entry names them.
    CHECK_THROWS_WITH(answer(400, gateway("invalid_request")), ContainsSubstring("HTTP 400") && ContainsSubstring("invalid_request") &&
                                                                    ContainsSubstring("turn-9"));
    CHECK_THROWS_WITH(answer(402, gateway("credits_exhausted")), ContainsSubstring("HTTP 402"));
    CHECK_THROWS_WITH(answer(502, "<html>Bad gateway</html>"), ContainsSubstring("HTTP 502") && ContainsSubstring("Bad gateway"));

    // Partway through a reply, in either format: the gateway's error event.
    for (const char* format : {kFormatAnthropic, kFormatResponses}) {
        DYNAMIC_SECTION("format " << format)
        {
            const auto event = [format](const std::string& code) {
                std::vector<AgentHttpRequest>             requests;
                std::vector<IAgentHttpTransport::EventFn> callbacks;
                AgentServicePtr                           agent = account_agent(format, requests, callbacks);
                AgentRequest                              request;
                JusPrinTest::kept_nowhere(request);
                request.request_id = "turn-9";
                request.user_text  = "hello";
                REQUIRE(agent->start(request));
                const json data = std::string(format) == kFormatAnthropic ?
                                      json{{"type", "error"}, {"error", {{"type", "api_error"}, {"code", code}, {"message", "words"}}}} :
                                      json{{"type", "error"}, {"code", code}, {"message", "words"}};
                callbacks.back()(AgentHttpEvent{AgentHttpEvent::Kind::Data, "event: error\\ndata: " + data.dump() + "\\n\\n", {}, 200});
                std::optional<AgentEvent> last = drain(*agent);
                REQUIRE(last.has_value());
                REQUIRE(last->error.has_value());
                return *last->error;
            };
            CHECK(event("timeout").code == "timeout");
            CHECK(event("unavailable").code == "service_unavailable");
            CHECK(event("server_error").code == "server_error");
            CHECK(event("server_error").message == "Something went wrong on our side");
            CHECK_THROWS_WITH(event("something_new"), ContainsSubstring("something_new") && ContainsSubstring("turn-9"));
        }
    }
}

