//   The provider too slow, or the line stalled    timed out                     Retry
//   No network                                    could not reach the service   Check the network, then Retry
//
// JusPrin's gateway names the cause with its own code; another service names
// it with its HTTP status, or inside a reply with its error type. Any other
// answer is unexpected: the request stops and the answer is thrown.
namespace {

AgentError rate_limited(const std::string& name)
{
    // TRN %1% is an AI provider, such as OpenAI.
    return {"rate_limited", Slic3r::format(translated(L("The %1% service is rate limited. Try again shortly.")), name), true};
