AgentError unavailable(const std::string& name)
{
    // TRN %1% is an AI provider, such as OpenAI.
    return {"service_unavailable", Slic3r::format(translated(L("The %1% service is temporarily unavailable.")), name), true};
}

AgentError too_large(const std::string& name)
{
    // TRN %1% is an AI provider, such as OpenAI.
    return {"request_too_large", Slic3r::format(translated(L("The request was too large for the %1% service.")), name), false};
}

AgentError timed_out() { return {"timeout", translated(L("The AI request timed out.")), true}; }

// The gateway's error body names its cause by code.
std::string gateway_code(const std::string& body)
{
    const json answer = json::parse(body, nullptr, false);
    if (!answer.is_object() || !answer.value("error", json()).is_object())
        return {};
    const json code = answer["error"].value("code", json());
    return code.is_string() ? code.get<std::string>() : std::string();
}

} // namespace

AgentError ProviderAgent::http_error(const AgentHttpEvent& event)
{
    // No answer at all: the connection failed or stalled before the service
    // said anything, or partway through a reply.
    if (event.status < 400) {
        if (event.error.find("timed out") != std::string::npos || event.error.find("Timeout") != std::string::npos)
            return timed_out();
        // TRN %1% is an AI provider, such as OpenAI.
        return {"network_error", Slic3r::format(translated(L("The AI request could not reach the %1% service.")), m_config.profile.display_name), true};
    }
    std::optional<AgentError> expected;
    if (m_config.profile.account_sign_in) {
        expected = update_required(event.status, event.data);
        if (!expected)
            expected = gateway_answer(gateway_code(event.data), event.data);
    } else {
        expected = provider_answer(event.status, event.data);
    }
    if (expected)
        return *expected;
    unexpected("answered HTTP " + std::to_string(event.status), event.data.empty() ? event.error : event.data);
}

AgentError ProviderAgent::stream_error(const StreamEvent& event)
{
    std::optional<AgentError> expected;
    if (!event.service_code.empty())
        expected = m_config.profile.account_sign_in ? gateway_answer(event.service_code, {}) : provider_event(event.service_code);
    if (expected)
        return *expected;
    unexpected(event.text, {});
}

std::optional<AgentError> ProviderAgent::gateway_answer(const std::string& code, const std::string& body) const
{
    const std::string& name = m_config.profile.display_name;
    if (code == "unauthorized")
        return AgentError{"invalid_credentials", translated(L("Your JusPrin sign-in has ended. Sign in again in Preferences, then try again.")), false};
    if (code == "credits_exhausted") {
        // What the message costs and what the person has, from the gateway's
        // numbers, in the app's language. The gateway always sends both.
        const json answer = json::parse(body, nullptr, false);
        if (!answer.is_object() || !answer.value("cost", json()).is_number_unsigned() || !answer.value("balance", json()).is_number_unsigned())
            return std::nullopt;
        const unsigned cost = answer["cost"].get<unsigned>();
        // TRN %1% is what the message costs in credits, %2% the credits the person has.
        return AgentError{"credits_exhausted",
                          Slic3r::format(translated_plural("This message needs %1% credit; you have %2%.",
                                                           "This message needs %1% credits; you have %2%.", cost),
                                         cost, answer["balance"].get<unsigned>()),
                          false};
    }
    // "busy": the gateway's own slots for large requests are all taken.
    if (code == "rate_limited" || code == "busy")
        return rate_limited(name);
    if (code == "request_too_large")
        return too_large(name);
    if (code == "unavailable")
        return unavailable(name);
    if (code == "timeout")
        return timed_out();
    // The gateway's own unexpected failure. It has reported it already, so
    // the person is told the same sentence and nothing is reported again.
    if (code == "server_error")
        return AgentError{"server_error", translated(L("Something went wrong on our side")), false};
    return std::nullopt;
}

std::optional<AgentError> ProviderAgent::provider_answer(unsigned status, const std::string& body) const
{
    const std::string& name = m_config.profile.display_name;
    if (status == 401)
        // TRN %1% is an AI provider, such as OpenAI.
        return AgentError{"invalid_credentials", Slic3r::format(translated(L("The %1% API key was rejected. Update the AI configuration and try again.")), name), false};
    if (status == 413)
        return too_large(name);
    // OpenAI answers 429 also when the key's account has no money left, a
    // cause no entry names.
    if (status == 429)
        return gateway_code(body) == "insufficient_quota" ? std::nullopt : std::optional<AgentError>(rate_limited(name));
    if (status == 529)
        return overloaded(name);
    if (status >= 500)
        return unavailable(name);
    if (status == 408)
        return timed_out();
    return std::nullopt;
}

std::optional<AgentError> ProviderAgent::provider_event(const std::string& code) const
{
    // The same causes as provider_answer's statuses, named inside a reply:
    // Anthropic's error types and OpenAI's error codes.
    const std::string& name = m_config.profile.display_name;
    if (code == "overloaded_error" || code == "server_is_overloaded")
        return overloaded(name);
    if (code == "rate_limit_error" || code == "rate_limit_exceeded")
        return rate_limited(name);
    if (code == "api_error" || code == "server_error")
        return unavailable(name);
    if (code == "request_too_large")
        return too_large(name);
    return std::nullopt;
}

void ProviderAgent::unexpected(const std::string& answered, const std::string& words)
{
    std::string what = m_config.profile.display_name + " " + answered + " to request " + m_transcript.request_id + " #" +
                       std::to_string(m_transcript.request_sequence);
    if (!m_service_request_id.empty())
        what += " (its request id " + m_service_request_id + ")";
    if (!words.empty())
        what += ": " + words;
    cancel();
    throw UnexpectedServiceAnswer(what);
}

